-- Short, visitor-facing wording; preserve identities, credits and review history.
WITH patches AS (SELECT value AS patch FROM jsonb_array_elements($copy$[{"id":"beach-guiwanon","description":"Guiwanon is a white-sand beach on Sibale Island, with a palm-lined shoreline. It is one of the beaches identified in Concepcion tourism references.","highlights":["White-sand coastline","Palm-lined shore","Sibale Island"],"entryFee":"Confirm locally","bestTime":"Confirm locally"},{"id":"beach-tonggo","description":"Tonggo is a beach area near the southern part of Sibale, also mapped as Tonggo Point Beaches. Its coastal scenery includes a sandy shore and green hills.","highlights":["Coastal scenery","Tonggo Point","Sandy shoreline"],"entryFee":"Confirm locally","bestTime":"Confirm locally"},{"id":"beach-tabunan","description":"Tabunan is one of Concepcion’s documented white-sand beaches. This listing is for Sibale Island, distinct from the beach of the same name on Banton Island.","highlights":["White-sand coastline","Sibale Island","Exact location unconfirmed"],"entryFee":"Confirm locally","bestTime":"Confirm locally"},{"id":"beach-quebrada","description":"Quebrada is a white-sand beach in the Poblacion Bay area. The bay and surrounding green hills form part of Concepcion’s coastal landscape.","highlights":["Poblacion Bay","White-sand shoreline","Bay and hillside views"],"entryFee":"Confirm locally","bestTime":"Confirm locally"},{"id":"landmark-lambirongan","description":"Lambirongan is a natural coastal stone arch identified among Concepcion’s attractions. Local travel accounts also use the spelling Lambirungan.","highlights":["Natural rock formation","Coastal landmark","Also spelled Lambirungan"],"entryFee":"Confirm locally","bestTime":"Confirm locally"},{"id":"culture-immaculate-grotto","description":"The Immaculate Conception Grotto is a Marian landmark associated with Mount Batareya on Sibale Island. It is distinct from the town’s Immaculate Conception Parish Church.","highlights":["Marian grotto","Mount Batareya","Cultural and religious landmark"],"entryFee":"Confirm locally","bestTime":"Confirm locally"}]$copy$::jsonb))
UPDATE resources r SET data=r.data||(patch-'id') FROM patches WHERE r.id=patch->>'id' AND r.kind='attraction';
